// ClipboardProvider — интерфейс доступа к системному буферу обмена.
type ClipboardProvider = base.ClipboardProvider

// ClipboardHTMLProvider — необязательное расширение ClipboardProvider: буфер,
// умеющий оформленный текст (HTML вместе с простым).
//
// Отдельный интерфейс, а не новые методы в ClipboardProvider: тот реализуют
// приложения, и добавление метода сломало бы каждую их реализацию. Провайдеры
// системного буфера (Windows, Wayland, X11) это расширение реализуют; свой
// провайдер приложения может его не поддерживать — тогда работает запасной
// путь SetClipboardHTML/ClipboardHTML.
type ClipboardHTMLProvider = base.ClipboardHTMLProvider

// SetClipboardProvider устанавливает глобальный провайдер буфера обмена.
func SetClipboardProvider(p ClipboardProvider) { base.SetClipboardProvider(p) }

// GetClipboardProvider возвращает текущий провайдер буфера обмена.
func GetClipboardProvider() ClipboardProvider { return base.GetClipboardProvider() }

// ClipboardGetText возвращает текст из системного буфера обмена.
func ClipboardGetText() string { return base.ClipboardGetText() }

// ClipboardSetText записывает текст в системный буфер обмена.
func ClipboardSetText(s string) { base.ClipboardSetText(s) }

// SetClipboardHTML кладёт в буфер обмена оформленный текст: html для тех, кто
// его понимает (Word, почтовик, браузерный редактор), и plain — для остальных
// (Блокнот, терминал).
//
// Если текущий провайдер HTML не умеет (приложение подставило свой, реализующий
// только ClipboardProvider), в буфер попадает только plain: оформление теряется,
// но скопированный текст не пропадает.
func SetClipboardHTML(html, plain string) { base.SetClipboardHTML(html, plain) }

// ClipboardHTML возвращает HTML из буфера обмена. ok == false, если HTML там
// нет, а также если текущий провайдер HTML не умеет: честно «нет», а не простой
// текст под видом разметки (его пришлось бы экранировать, и вызывающий не
// отличил бы одно от другого). Запасной путь для вызывающего — ClipboardGetText.
func ClipboardHTML() (html string, ok bool) { return base.ClipboardHTML() }

// UseMemoryClipboard переключает буфер обмена на детерминированную in-memory
// реализацию (без интеграции с ОС). Предназначено для тестов и headless-сценариев,
// где зависимость от глобального системного буфера обмена даёт нестабильность.
func UseMemoryClipboard() { base.UseMemoryClipboard() }

// ── clipboard_files.go ──

// ClipboardFilesProvider — необязательное расширение ClipboardProvider: буфер,
// умеющий список файлов.
type ClipboardFilesProvider = base.ClipboardFilesProvider

// ClipboardSetFiles кладёт в системный буфер обмена список файлов (абсолютные
// пути), заменяя его содержимое, как ClipboardSetText. cut — вырезать, а не
// копировать: файловый менеджер, куда вставят, переместит файлы.
//
// Рядом в буфер ложатся те же пути простым текстом, через перевод строки, —
// для программ, которые берут только текст. Если текущий провайдер файлы не
// умеет, ложится только этот текст.
func ClipboardSetFiles(paths []string, cut bool) { base.ClipboardSetFiles(paths, cut) }

// ClipboardFiles читает список файлов из системного буфера обмена. ok == false,
// если в буфере не файлы или провайдер их не умеет. cut — файлы вырезали.
//
// Вызов может ЖДАТЬ: владелец буфера отдаёт данные, когда готов, а на
// удалённом рабочем столе файлы, скопированные у клиента, скачиваются в
// момент вставки — секунды и дольше. Поэтому звать его стоит не на горутине
// движка (там рисуется кадр), а в своей, с результатом через Engine.Post.
func ClipboardFiles() (paths []string, cut bool, ok bool) { return base.ClipboardFiles() }

// ── clipboard_formats.go ──

// ClipboardFormatSet — набор видов содержимого, которые есть в буфере обмена.
// Один и тот же буфер несёт сразу несколько видов: скопированные файлы лежат
// и списком, и текстом путей; оформленный текст — и HTML, и простым.
type ClipboardFormatSet = base.ClipboardFormatSet

const (
	// ClipboardFormatText — простой текст (ClipboardGetText).
	ClipboardFormatText = base.ClipboardFormatText
	// ClipboardFormatHTML — оформленный текст (ClipboardHTML).
	ClipboardFormatHTML = base.ClipboardFormatHTML
	// ClipboardFormatImage — изображение (ClipboardImage).
	ClipboardFormatImage = base.ClipboardFormatImage
	// ClipboardFormatFiles — файлы (ClipboardFiles): готовый список или
	// «обещанные» файлы, которые владелец отдаст при вставке.
	ClipboardFormatFiles = base.ClipboardFormatFiles
)

// ClipboardFormatsProvider — необязательное расширение ClipboardProvider:
// буфер, умеющий быстро сказать, какие виды содержимого в нём лежат.
type ClipboardFormatsProvider = base.ClipboardFormatsProvider

// ClipboardFormats возвращает набор видов содержимого системного буфера
// обмена: текст, HTML, изображение, файлы. Содержимое НЕ читается, а чужой
// владелец буфера не ждётся дольше короткого предела (на X11 — 250 мс на
// первый вопрос, дальше ответ берётся из памяти), так что вызов можно делать
// при каждом изменении буфера. Зовите вне замков: в худшем случае (X11,
// владелец молчит) вызов занимает эти 250 мс.
//
// Если провайдер приложения расширения ClipboardFormatsProvider не реализует,
// возвращается пустой набор: честное «не знаю», а не чтение через
// ClipboardFiles и ClipboardImage, которое могло бы ждать неограниченно.
func ClipboardFormats() ClipboardFormatSet { return base.ClipboardFormats() }

// ClipboardHasFiles сообщает, лежат ли в системном буфере обмена файлы
// (ClipboardFiles вернул бы ok == true), не читая их список и не дожидаясь
// владельца буфера. Это ClipboardFormats().Has(ClipboardFormatFiles); оговорки
// те же.
//
// На Windows «файлы» — это и готовый список (CF_HDROP), и «обещанные» файлы
// (FileGroupDescriptorW), которые владелец отдаёт при вставке. Положительный
// ответ говорит, что владелец ОБЪЯВИЛ файлы, но не что ClipboardFiles сумеет их
// прочитать: список может не разобраться, а владелец — не ответить.
func ClipboardHasFiles() bool { return base.ClipboardHasFiles() }

// ── clipboard_html.go ──

// BuildCFHTML собирает данные формата «HTML Format» из HTML-фрагмента.
//
// Если на входе целый документ (есть <body>), маркеры фрагмента ставятся
// внутри тела; иначе фрагмент оборачивается в минимальный документ. Результат
// не содержит завершающего NUL — его добавляет тот, кто кладёт данные в
// буфер, потому что NUL не входит ни в одно из смещений.
//
// Функция экспортирована, чтобы приложение могло проверить или переиспользовать
// формат (например, для перетаскивания), и потому что платформенный файл
// Windows — не единственный потребитель.
func BuildCFHTML(fragment string) []byte { return base.BuildCFHTML(fragment) }

// ParseCFHTML достаёт HTML-фрагмент из данных формата «HTML Format».
//
// Чужие приложения пишут этот формат по-разному: смещения бывают без ведущих
// нулей, строки заканчиваются и \n, и \r\n, в конце может стоять NUL, а
// иногда в буфер кладут вовсе голый HTML без заголовка. Всё это принимается.
// Недостоверные смещения (за пределами данных, начало позже конца) не
// доверяются: данные приходят извне, и слепой срез по чужому числу — паника.
// ok == false, если фрагмента нет или он пуст.
func ParseCFHTML(data []byte) (fragment string, ok bool) { return base.ParseCFHTML(data) }

// ── clipboard_image.go ──

// ErrClipboardImageUnsupported возвращается ClipboardSetImage, когда текущий
// провайдер буфера обмена изображений не умеет (приложение подставило свой,
// реализующий только ClipboardProvider, либо платформа без поддержки).
var ErrClipboardImageUnsupported = base.ErrClipboardImageUnsupported

// ErrClipboardImageEmpty возвращается ClipboardSetImage для nil и пустой
// картинки: класть в буфер нечего.
var ErrClipboardImageEmpty = base.ErrClipboardImageEmpty

// ClipboardImageProvider — необязательное расширение ClipboardProvider: буфер,
// умеющий изображения.
type ClipboardImageProvider = base.ClipboardImageProvider

// ClipboardSetImage кладёт изображение в системный буфер обмена, заменяя его
// содержимое, как ClipboardSetText.
//
// Прозрачность сохраняется там, где формат её несёт (PNG, CF_DIBV5); в
// 24-битном CF_DIB, который берут старые программы, она смешивается с белым.
// Возвращает ErrClipboardImageUnsupported, если провайдер изображений не
// умеет, и ErrClipboardImageEmpty для пустой картинки.
func ClipboardSetImage(img image.Image) error { return base.ClipboardSetImage(img) }

// ClipboardImage читает изображение из системного буфера обмена. ok == false,
// если в буфере не изображение или провайдер их не умеет.
//
// Вызов может ЖДАТЬ: владелец буфера отдаёт данные, когда готов (на X11 и
// Wayland — до 300 мс на ответ владельца, дальше столько же на каждый кусок
// большой картинки), а картинка потом декодируется. Поэтому звать его стоит не
// на горутине движка (там рисуется кадр), а в своей, с результатом через
// Engine.Post — как ClipboardFiles.
func ClipboardImage() (img image.Image, ok bool) { return base.ClipboardImage() }

// ── clipboard_virtual.go ──

// VirtualFile — файл, обещанный буферу обмена без содержимого.
type VirtualFile = base.VirtualFile

var (
	// ErrClipboardVirtualUnsupported возвращает ClipboardSetVirtualFiles, когда
	// текущий буфер виртуальных файлов не умеет (macOS, провайдер приложения без
	// расширения, Linux без окна). Совпадает с errors.ErrUnsupported.
	ErrClipboardVirtualUnsupported = base.ErrClipboardVirtualUnsupported
	// ErrClipboardVirtualEmpty — список пуст или не задан ни open, ни
	// WithMaterialize: класть в буфер нечего.
	ErrClipboardVirtualEmpty = base.ErrClipboardVirtualEmpty
	// ErrClipboardVirtualNoSource — платформе нужна функция, которой приложение
	// не дало: на Windows это open, на X11 и Wayland — WithMaterialize. Буфер
	// при этом не меняется. Совпадает с errors.ErrUnsupported.
	ErrClipboardVirtualNoSource = base.ErrClipboardVirtualNoSource
	// ErrVirtualFileName — недопустимое имя виртуального файла или список, где
	// имена противоречат друг другу.
	ErrVirtualFileName = base.ErrVirtualFileName
	// ErrVirtualFileNotFound — обещания в буфере нет или индекс вне списка.
	ErrVirtualFileNotFound = base.ErrVirtualFileNotFound
)

// NormalizeVirtualFiles проверяет список и возвращает его копию с
// приведёнными именами (без завершающего «/»).
//
// Имя — относительный путь из непустых компонентов, без «.», «..», обратной
// косой черты, нулевого и управляющих символов, в корректном UTF-8. Одно имя
// дважды и «файл, он же каталог» (имя файла как префикс пути другого) — отказ:
// приёмник создал бы либо перезапись, либо несуществующий каталог. Размер не
// отрицателен. Ошибка оборачивает ErrVirtualFileName.
func NormalizeVirtualFiles(files []VirtualFile) ([]VirtualFile, error) {
	return base.NormalizeVirtualFiles(files)
}

// VirtualTopLevel возвращает индексы записей верхнего уровня (имя без «/»).
// Ошибка (ErrVirtualFileName), если вложенная запись лежит в каталоге верхнего
// уровня, которого нет в списке явной записью IsDir. Нужна X11 и Wayland: пути
// просят только у записей верхнего уровня.
func VirtualTopLevel(files []VirtualFile) ([]int, error) { return base.VirtualTopLevel(files) }

// VirtualFilesOptions — необязательные колбэки приложения для
// ClipboardSetVirtualFiles; заполняются VirtualFilesOption.
type VirtualFilesOptions = base.VirtualFilesOptions

// VirtualFilesOption настраивает ClipboardSetVirtualFiles.
type VirtualFilesOption = base.VirtualFilesOption

// WithMaterialize задаёт колбэк X11 и Wayland: вставляющему нужен настоящий
// путь, и движок просит его у приложения в момент запроса text/uri-list или
// x-special/gnome-copied-files.
//
// fn(index) зовётся для каждой записи верхнего уровня списка (имя без «/»):
// для файла приложение кладёт его на диск и возвращает абсолютный путь, для
// каталога — каталог со всем содержимым (вложенные записи сами в колбэк не
// попадают). Каталог верхнего уровня обязан быть в списке явной записью IsDir —
// иначе спросить не о чем, и ClipboardSetVirtualFiles отвечает
// ErrVirtualFileName. Вызов задерживает ответ владельца выделения, вставляющий
// ждёт; зовётся не на горутине движка, последовательно для одного обещания.
// Результат запоминается до снятия обещания: второй запрос (uri-list после
// gnome-copied-files) повторно не зовёт. Ошибка не запоминается и значит
// отказ вставляющему. На Windows игнорируется.
func WithMaterialize(fn func(index int) (path string, err error)) VirtualFilesOption {
	return base.WithMaterialize(fn)
}

// WithRelease задаёт колбэк «обещание снято»: буфер заменили другим
// содержимым, закрыли окно или вызвали ClipboardCleanup. Здесь приложение
// убирает то, что положило на диск. Зовётся один раз, в отдельной горутине,
// из него нельзя ждать другие вызовы буфера обмена.
func WithRelease(fn func()) VirtualFilesOption { return base.WithRelease(fn) }

// ClipboardVirtualFilesProvider — необязательное расширение ClipboardProvider:
// буфер, умеющий виртуальные файлы.
type ClipboardVirtualFilesProvider = base.ClipboardVirtualFilesProvider

// ClipboardSetVirtualFiles кладёт в системный буфер обмена «обещанные» файлы:
// имена, размеры и время изменения — без содержимого. Содержимое запрашивается
// у приложения только тогда, когда файлы вставляют.
//
// Windows: open(index) вернёт читателя файла files[index] (для каталогов не
// зовётся); Проводник вставляет файлы как обычные, а содержимое читает потоком
// IStream, поэтому open вызывается при первом чтении, и читатель закрывается
// после него. Чтение идёт на отдельном потоке ОС, обслуживающем буфер, куском
// за раз; пока кусок не прочитан, замена буфера из другого потока ждёт.
// WithMaterialize игнорируется.
//
// X11 и Wayland: стандартного протокола «виртуальных файлов» нет, поэтому в
// ответ на запрос text/uri-list или x-special/gnome-copied-files владелец
// зовёт WithMaterialize и отдаёт вернувшиеся пути. Ограничение: такой запрос
// иногда делают и менеджеры буфера обмена просто при просмотре — тогда
// колбэк вызовется без вставки; часть программ (Qt — 5 секунд) ждёт ответ
// владельца ограниченное время. Простым текстом ложатся только относительные
// имена. open на этих платформах нужен лишь ClipboardOpenVirtualFile.
// Движок ничего не создаёт и не удаляет на диске.
//
// Колбэки зовутся не на горутине движка. Буфер заменяется так же, как в
// ClipboardSetText; когда его заменят (или вызовут ClipboardCleanup),
// обещание снимается и зовётся WithRelease.
//
// Ошибки: ErrClipboardVirtualUnsupported (macOS, провайдер без расширения),
// ErrClipboardVirtualEmpty (пустой список, нет ни open, ни WithMaterialize),
// ErrClipboardVirtualNoSource (платформе не хватает своей функции; буфер не
// меняется), ErrVirtualFileName (недопустимые имена).
func ClipboardSetVirtualFiles(files []VirtualFile, open func(index int) (io.ReadCloser, error), opts ...VirtualFilesOption) error {
	return base.ClipboardSetVirtualFiles(files, open, opts...)
}

// ClipboardVirtualFiles возвращает файлы, обещанные ClipboardSetVirtualFiles,
// пока они в буфере. ok == false, если буфер уже заменён или провайдер
// виртуальных файлов не умеет.
func ClipboardVirtualFiles() (files []VirtualFile, ok bool) { return base.ClipboardVirtualFiles() }

// ClipboardOpenVirtualFile открывает содержимое файла index из нашего же
// обещания — как вставка внутри программы. Ошибка, если обещания в буфере нет,
// индекс вне списка или open не задан.
func ClipboardOpenVirtualFile(index int) (io.ReadCloser, error) {
	return base.ClipboardOpenVirtualFile(index)
}

// ClipboardCleanup снимает обещание виртуальных файлов, если оно ещё в буфере
// (зовётся WithRelease). Звать при выходе из программы. Провайдер без такой
// возможности игнорируется.
func ClipboardCleanup() { base.ClipboardCleanup() }

