// DragState хранит состояние перетаскивания панели.
// Встраивается в Panel через поле Drag.
type DragState = base.DragState

// Dismissable реализуется виджетами с раскрывающимся состоянием
// (dropdown, popup, menu), которые нужно закрыть при внешнем событии (drag и т.п.).
type Dismissable = base.Dismissable

// DismissableAt — виджет, которому для решения о закрытии нужна точка клика.
//
// Движок предпочитает его обычному Dismissable: закрывать себя по факту
// «клик пришёлся не в меня» умеет и Dismissable, но не всякий виджет считает
// чужой площадью всё, что вне его собственной. Всплывающие панели рабочего
// стола, стоящие одна над другой, — набор, в котором площадь соседки своя
// (desktop.FlyoutGroup).
type DismissableAt = base.DismissableAt

// EscapeDismisser — виджет, который закрывается по Esc независимо от того, где
// клавиатурный фокус: всплывающая панель рабочего стола, у которой фокуса
// может не быть вовсе.
//
// Движок зовёт DismissOnEscape у таких виджетов по нажатию Esc, прежде чем
// отдать клавишу виджету с фокусом (см. DismissOnEscape). Метод возвращает
// true, если что-то закрыл: тогда клавиша считается обработанной.
type EscapeDismisser = base.EscapeDismisser

// DismissOnEscape обходит поддерево w от верхних слоёв к нижним (последний
// ребёнок — верхний) и закрывает ПЕРВЫЙ найденный EscapeDismisser, у которого
// есть что закрывать. Один Esc — один слой: открытые друг над другом панели
// закрываются по очереди, сверху вниз. Возвращает true, если что-то закрыто.
func DismissOnEscape(w Widget) bool { return base.DismissOnEscape(w) }

// DismissAll рекурсивно закрывает все Dismissable-виджеты в поддереве w.
func DismissAll(w Widget) { base.DismissAll(w) }

// BaseBoundsProvider реализуется виджетами, которые переопределяют Bounds()
// (например, Dropdown расширяет bounds при открытом списке). ShiftWidget
// использует BaseBounds() чтобы сдвигать именно базовый прямоугольник,
// не раздувая его от кадра к кадру.
type BaseBoundsProvider = base.BaseBoundsProvider

// ShiftWidget сдвигает bounds виджета и всех его потомков на (dx, dy).
// Если виджет реализует BaseBoundsProvider — использует базовые bounds,
// иначе берёт Bounds().
func ShiftWidget(w Widget, dx, dy int) { base.ShiftWidget(w, dx, dy) }

// ── drawtrace.go ──

// EnableDrawTrace включает учёт рисующихся виджетов и возвращает функцию,
// которая его выключает. Включений может быть несколько, учёт работает, пока
// не выключено последнее; повторный вызов возвращённой функции ничего не
// делает.
func EnableDrawTrace() (disable func()) { return base.EnableDrawTrace() }

// DrawTraceUsers — сколько включений учёта не выключено. Для тестов: учёт
// общий на процесс, и забытое включение замедляет кадры всех движков.
func DrawTraceUsers() int { return base.DrawTraceUsers() }

// DrawTraced рисует w, отмечая его рисующимся на время Draw, а сломанный —
// заменяет заглушкой. Пока учёт выключен и сломанных нет — то же, что
// w.Draw(ctx). Для контейнеров, которые обходят детей своим циклом, а не
// через DrawChildren.
//
// Под рекордером команд (retain.go) это единственная точка входа удержания:
// Draw виджета с верным списком не зовётся вовсе.
//
// Обёртка короткая: при нулевом медленном пути она компилируется в тот же
// вызов, что и прежде. Ветка с учётом вынесена отдельно — функция с defer не
// встраивается, и контекст, переданный через неё, уходил бы в кучу на каждом
// кадре (тест попапов без аллокаций это ловит).
func DrawTraced(w Widget, ctx DrawContext) { base.DrawTraced(w, ctx) }

// DrawOverlayTraced рисует оверлей виджета w (выпадающий список, меню),
// отмечая w рисующимся; у сломанного виджета оверлей не рисуется. Устроена
// как DrawTraced.
func DrawOverlayTraced(w Widget, od OverlayDrawer, ctx DrawContext) {
	base.DrawOverlayTraced(w, od, ctx)
}

// DrawTracePath возвращает виджеты, рисующиеся сейчас на вызывающей горутине,
// от внешнего к внутреннему (последний — тот, чей Draw идёт). nil — учёт
// выключен или ничего не рисуется. Срез — копия.
func DrawTracePath() []Widget { return base.DrawTracePath() }

// ResetDrawTrace забывает стек рисующихся на вызывающей горутине. Движок зовёт
// это после паники в Draw: раскрутка стека прошла мимо popDrawTrace, и без
// сброса следующий кадр начинал бы с чужого хвоста.
func ResetDrawTrace() { base.ResetDrawTrace() }

