	// что на них написано в раскладке США, — так же, как у Windows, чьи
	// значения здесь и взяты.
	KeyOemSemicolon  = base.KeyOemSemicolon  // ;: — VK_OEM_1
	KeyOemPlus       = base.KeyOemPlus       // =+ — одинаков во всех раскладках
	KeyOemComma      = base.KeyOemComma      // ,<
