	KeyOemTilde      = base.KeyOemTilde      // `~ — VK_OEM_3
	KeyOemOpenBrace  = base.KeyOemOpenBrace  // [{ — VK_OEM_4
	KeyOemBackslash  = base.KeyOemBackslash  // \| — VK_OEM_5
	KeyOemCloseBrace = base.KeyOemCloseBrace // ]} — VK_OEM_6
	KeyOemQuote      = base.KeyOemQuote      // '" — VK_OEM_7
	// Модификаторы как клавиши. Раньше Shift/Ctrl/Alt жили только в
	// KeyEvent.Mod, а сами нажатия до виджетов не доходили; клиенту удалённого
