// MenuBarItem описывает один пункт верхнего горизонтального меню.
type MenuBarItem = base.MenuBarItem

// MenuBar — горизонтальная полоса меню (Menu / MainMenu) в стиле Windows.
//
// Каждый пункт верхнего уровня отображается горизонтально. При клике
// раскрывается PopupMenu с подпунктами. При наведении на соседний пункт
// подменю автоматически переключается.
//
// Поддержка XAML:
//
//	<Menu Name="mainMenu" Left="0" Top="0" Width="800" Height="28">
//	    <MenuItem Header="Файл">
//	        <MenuItem Text="Новый"/>
//	        <MenuItem Text="Открыть"/>
//	        <MenuItem Separator="True"/>
//	        <MenuItem Text="Выход"/>
//	    </MenuItem>
//	    <MenuItem Header="Правка">
//	        <MenuItem Text="Копировать"/>
//	        <MenuItem Text="Вставить"/>
//	    </MenuItem>
//	</Menu>
type MenuBar = base.MenuBar

// NewMenuBar создаёт пустую горизонтальную панель меню.
func NewMenuBar() *MenuBar { return base.NewMenuBar() }

// ── menubutton.go ──

// MenuButton — кнопка с выпадающим меню.
//
// Два вида. Разделённая (Split, NewSplitButton): основная часть выполняет
// OnClick, стрелка справа открывает меню. Простая (NewMenuButton): меню
// открывает вся кнопка, OnClick не зовётся.
//
// Внешний вид, тема, значок, подпись и подсказка — от встроенной Button.
type MenuButton = base.MenuButton

// NewMenuButton создаёт кнопку, целиком открывающую меню.
func NewMenuButton(text string) *MenuButton { return base.NewMenuButton(text) }

// NewSplitButton создаёт разделённую кнопку: onClick — действие основной
// части, меню открывает стрелка.
func NewSplitButton(text string, onClick func()) *MenuButton {
	return base.NewSplitButton(text, onClick)
}

