// ── move.go ──

// MoveNotice — объявленный перенос: откуда взять и куда положить.
type MoveNotice = base.MoveNotice

// RegisterMoveSink регистрирует приёмник объявлений о переносе и возвращает
// дескриптор для UnregisterMoveSink. Движок вызывает это при создании.
//
// Приёмник получает КАЖДОЕ объявление процесса и сам решает, относится ли
// оно к его дереву. Виджет об этом ничего не знает: он говорит «эти пиксели
// переехали», а не «переехали у такого-то движка».
func RegisterMoveSink(notify func(MoveNotice)) uint64 { return base.RegisterMoveSink(notify) }

// RegisterMoveSinkFor — RegisterMoveSink для приёмника-движка, владеющего
// деревьями (ADR-0008): объявления виджета, чьё дерево привязано к другому
// владельцу, до него не доходят. owner == nil — наблюдатель.
func RegisterMoveSinkFor(owner Owner, notify func(MoveNotice)) uint64 {
	return base.RegisterMoveSinkFor(owner, notify)
}

// UnregisterMoveSink снимает приёмник по дескриптору. Идемпотентно.
func UnregisterMoveSink(handle uint64) { base.UnregisterMoveSink(handle) }

// NotifyMove объявляет, что содержимое области src целиком переехало в dst.
//
// Размер берётся у dst; если он не совпадает с размером источника, это уже
// не перенос, а масштабирование — такое объявление отбрасывается, потому что
// потребитель выполнит его блитом и получит искажение.
//
// Объявление НЕ отменяет обычную инвалидацию: виджет по-прежнему обязан
// заявить изменившиеся области. Перенос — подсказка, как дешевле получить тот
// же результат, а не замена damage.
func NotifyMove(src, dst image.Rectangle) { base.NotifyMove(src, dst) }

// NotifyWidgetMove — то же самое, но с указанием, чьё содержимое переехало.
//
// Виджет из дерева обязан звать именно её: движки в одном процессе получают
// все объявления, и без виджета отличить своё от чужого можно только по
// координатам — а у двух движков одного разрешения они совпадают.
func NotifyWidgetMove(w Widget, src, dst image.Rectangle) { base.NotifyWidgetMove(w, src, dst) }

