func CurrentTheme() *Theme { return base.CurrentTheme() }

// ── theme_bridge.go ──

// ProfileFromTheme собирает профиль токенов из плоской темы.
//
// Нужен, чтобы шесть готовых пресетов стали профилями без переписывания
// палитры вручную: тема, собранная сегодня в коде, немедленно доступна
// новой модели. Имя профиля берётся из ThemeStyle.Name, если оно задано.
func ProfileFromTheme(t *Theme) *theme.Profile { return base.ProfileFromTheme(t) }

// Materialize собирает плоскую тему из разрешённой темы токенов.
//
// Это и есть обещание совместимости: код, который знает только
// widget.Theme, получает её из профиля и не замечает, что палитра теперь
// живёт в другой модели.
func Materialize(rt *theme.Theme) *Theme { return base.Materialize(rt) }

// ── theme_registry.go ──

// DefaultThemeManager возвращает менеджер тем, в котором уже зарегистрированы
// все встроенные пресеты — те же, что отдаёт ThemeNames.
//
// Мост работает в обе стороны, и приложению не нужно выбирать сторону сразу:
// старый путь (ThemeByName + Engine.SetTheme) продолжает работать, а этот
// менеджер даёт те же темы в новой модели — с наследованием, покомпонентными
// правилами и подпиской на смену. Профиль можно унаследовать от встроенного
// и переопределить десяток токенов, не переписывая палитру.
//
// Менеджер один на процесс — как и активная тема, которую он держит.
// Приложению, которому нужен свой набор (несколько окон с разным
// оформлением), стоит завести собственный theme.NewManager.
func DefaultThemeManager() *theme.Manager { return base.DefaultThemeManager() }

// ThemeFromProfile собирает плоскую тему по имени профиля из менеджера.
// Возвращает nil, если такого профиля нет или его не удалось разрешить
// (не зарегистрирован родитель, цикл наследования).
func ThemeFromProfile(m *theme.Manager, name string) *Theme { return base.ThemeFromProfile(m, name) }

// ── themeicons.go ──

// IconSet — реализация theme.IconResolver: реестр иконок темы.
//
// Источник иконки — SVG-файл под baseDir (IconRef.Source) либо заранее
// зарегистрированные данные/изображение (IconRef.Name). Если заданы оба —
// приоритет у Name: зарегистрированное важнее файла.
//
// Все методы безопасны для вызова из нескольких горутин — ResolveIcon зовут
// из отрисовки, Register/RegisterImage могут прийти в это же время из
// загрузки темы.
type IconSet = base.IconSet

// NewIconSet создаёт пустой набор иконок. baseDir — каталог, относительно
// которого разрешаются пути IconRef.Source; выход за его пределы («../…»)
// отклоняется тем же способом, что и ресурсы XAML (SEC-8,
// ResolveResource) — см. resources.go.
func NewIconSet(baseDir string) *IconSet { return base.NewIconSet(baseDir) }

// NewIconSetFS создаёт набор иконок, читающий SVG-файлы IconRef.Source из
// файловой системы fsys — вшитого каталога (go:embed) или любой другой fs.FS —
// вместо диска. Оптические размеры (IconRef.Sizes с «{size}» в Source) работают
// так же, как у NewIconSet: файл выбирается по запрошенному размеру.
//
// dir — подкаталог fsys, от которого разрешаются пути Source («» — корень).
// Пути пишутся через «/» (обратная косая тоже принимается); абсолютный путь и
// выход за пределы dir («../…») отклоняются, как и у NewIconSet (SEC-8), —
// иконка получает заглушку.
//
//	//go:embed icons/*.svg
//	var iconsFS embed.FS
//	set := widget.NewIconSetFS(iconsFS, "icons")
//	ref := theme.IconRef{Source: "wifi_{size}.svg", Sizes: theme.IconSizes(16, 20, 24)}
func NewIconSetFS(fsys fs.FS, dir string) *IconSet { return base.NewIconSetFS(fsys, dir) }

// BuiltinIcons — набор иконок панели задач, не требующий ни одного файла на
// диске: имена регистрируются как генераторы, рисующие *image.RGBA
// примитивами (прямоугольники, линии) под запрошенный размер.
func BuiltinIcons() *IconSet { return base.BuiltinIcons() }

